class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        if k == 0:
            return '0' * n

        # If k is greater than 9, it's impossible to form a valid palindrome
        if k > 9:
            return '0' * n

        # If n is 1, the largest palindrome is simply the number itself
        if n == 1:
            return str(k)

        # For even n, the palindrome can be formed by repeating the middle digit
        if n % 2 == 0:
            mid_digit = k // 2
            return f"{mid_digit}{mid_digit}"

        # For odd n, the palindrome can be formed by repeating the middle digit and adding one more on each side
        else:
            mid_digit = k // 2
            left_side = str(mid_digit)
            right_side = str(mid_digit + 1)
            return f"{left_side}{right_side}{left_side}"

