class Solution:
    def findSafeWalk(self, grid: List[List[int]], health: int) -> bool:
        m, n = len(grid), len(grid[0])
        dp = [[-1] * n for _ in range(m)]
        dp[m-1][n-1] = health

        for i in range(m-1, -1, -1):
            for j in range(n-1, -1, -1):
                if grid[i][j] == 1:
                    health -= 1

                if health < 0:
                    continue

                if i+1 < m:
                    dp[i][j] = max(dp[i][j], dp[i+1][j]+health)

                if j+1 < n:
                    dp[i][j] = max(dp[i][j], dp[i][j+1]+health)

                if i-1 >= 0:
                    dp[i][j] = max(dp[i][j], dp[i-1][j]+health)

                if j-1 >= 0:
                    dp[i][j] = max(dp[i][j], dp[i][j-1]+health)

        return dp[0][0] >= 0

