class Solution:
    def validSequence(self, word1: str, word2: str) -> List[int]:
        n, m = len(word1), len(word2)
        dp = [[float('inf')] * m for _ in range(n)]
        dp[0][0] = 0

        for i in range(1, n):
            for j in range(m):
                if word1[i] == word2[j]:
                    dp[i][j] = min(dp[i][j], dp[i-1][j])
                else:
                    dp[i][j] = min(dp[i][j], dp[i-1][j+1])

        result = []
        i, j = n - 1, m - 1
        while i >= 0:
            if word1[i] == word2[j]:
                result.append(i)
                i -= 1
                j -= 1
            elif dp[i][j] == dp[i-1][j+1]:
                result.append(i)
                i -= 1
            else:
                result.append(i)
                i -= 1
                j += 1

        result.reverse()
        return result

