class Solution:
    def remainingMethods(self, n: int, k: int, invocations: List[List[int]]) -> List[int]:
        graph = [[] for _ in range(n)]
        for a, b in invocations:
            graph[a].append(b)

        # Topological sort to find the order of removal
        stack = [k]
        visited = set()
        while stack:
            node = stack.pop()
            visited.add(node)
            for neighbor in graph[node]:
                if neighbor not in visited:
                    stack.append(neighbor)

        # Remove the nodes in the order found
        result = [i for i in range(n) if i not in visited]
        return result

