class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        MOD = 10**9 + 7

        # Initialize dp array where dp[i][j] represents the number of ways to assign i performers to j stages
        dp = [[0] * (y+1) for _ in range(n+1)]

        # Base case: There's exactly one way to assign 0 performers to any number of stages
        for j in range(1, y+1):
            dp[0][j] = 1

        # Fill the dp array
        for i in range(1, n+1):
            for j in range(1, y+1):
                if j == x:
                    dp[i][j] = (dp[i-1][x] + dp[i-1][y]) % MOD
                elif j == y:
                    dp[i][j] = (dp[i-1][x] + dp[i-1][y]) % MOD
                else:
                    dp[i][j] = (dp[i-1][x] + dp[i-1][y]) % MOD

        return dp[n][y]

