def kthLargestPerfectSubtree(self, root: Optional[TreeNode], k: int) -> int:
        def dfs(node):
            if not node:
                return 0

            left_size = dfs(node.left)
            right_size = dfs(node.right)

            # Calculate the size of the current perfect binary subtree
            size = left_size + right_size + 1

            # If we have found the kth largest size, return it
            if size == k:
                return size

            # Otherwise, continue searching in the appropriate direction
            if size > k:
                return dfs(node.left)
            else:
                return dfs(node.right)

        # Start the DFS from the root
        return dfs(root)

