class Solution:
    def smallestNumber(self, num: str, t: int) -> str:
        if t == 1:
            return num

        # Remove trailing zeros
        num = num.rstrip('0')

        # Check if the number is already divisible by t
        if int(num) % t == 0:
            return num

        # Find the first non-zero digit from the right
        for i in range(len(num) - 1, -1, -1):
            if num[i] != '0':
                break

        # Replace the found digit with the smallest possible digit
        num = num[:i] + '0' + num[i+1:]

        # Check if the new number is divisible by t
        if int(num) % t == 0:
            return num

        return '-1'

