    def maxRectangleArea(self, xCoord: List[int], yCoord: List[int]) -> int:
        if len(xCoord) < 2:
            return -1

        xCoord.sort()
        yCoord.sort()

        max_area = 0
        for i in range(len(xCoord)):
            min_y = yCoord[0]
            for j in range(i + 1, len(xCoord)):
                max_y = max(max_y, yCoord[j])
                width = xCoord[j] - xCoord[i]
                height = max_y - min_y
                max_area = max(max_area, width * height)

        return max_area

