class Solution:
    def maxAmount(self, initialCurrency: str, pairs1: List[List[str]], rates1: List[float], pairs2: List[List[str]], rates2: List[float]) -> float:
        graph1 = defaultdict(list)
        graph2 = defaultdict(list)

        for u, v in pairs1:
            graph1[u].append((v, rates1[pairs1.index([u, v])]))
            graph2[v].append((u, 1/rates1[pairs1.index([u, v])]))

        for u, v in pairs2:
            graph1[u].append((v, rates2[pairs2.index([u, v])]))
            graph2[v].append((u, 1/rates2[pairs2.index([u, v])]))

        visited = set()
        stack = [(initialCurrency, 1)]
        max_amount = 0

        while stack:
            curr_currency, curr_rate = stack.pop()

            if curr_currency not in visited:
                visited.add(curr_currency)
                max_amount = max(max_amount, curr_rate * self.dfs(graph1, curr_currency, visited))
                max_amount = max(max_amount, curr_rate * self.dfs(graph2, curr_currency, visited))

        return max_amount

    def dfs(self, graph, curr_currency, visited):
        if curr_currency in visited:
            return 0

        visited.add(curr_currency)
        max_amount = 0

        for neighbor, rate in graph[curr_currency]:
            max_amount = max(max_amount, rate + self.dfs(graph, neighbor, visited))

        return max_amount

