class Solution:
    def countPathsWithXorValue(self, grid: List[List[int]], k: int) -> int:
        MOD = 10**9 + 7

        @cache
        def dfs(i, j, xor):
            if i >= len(grid) or j >= len(grid[0]) or xor > k:
                return 0

            if i == len(grid) - 1 and j == len(grid[0]) - 1:
                return 1 if xor == k else 0

            return (dfs(i+1, j, xor ^ grid[i][j]) + dfs(i, j+1, xor ^ grid[i][j])) % MOD

        return dfs(0, 0, 0)

