        count = Counter(nums)
        max_count = max(count.values())
        if max_count < 5:
            return 0

        ans = 0
        for num in count.keys():
            if count[num] == max_count:
                ans += self.comb(max_count - 1, 4)

        return ans % (10**9 + 7)

    def comb(self, n, k):
        if k > n // 2:
            k = n - k
        res = 1
        for i in range(1, k + 1):
            res *= (n - i + 1)
            res //= i
        return res

