class Solution:
    def countGoodArrays(self, n: int, m: int, k: int) -> int:
        if k == 0:
            return 2

        mod = 10**9 + 7
        dp = [[0 for _ in range(k+1)] for _ in range(m+1)]
        dp[0][0] = 1

        for i in range(1, m+1):
            for j in range(1, min(i, k)+1):
                dp[i][j] = (dp[i-1][j] + dp[i-1][j-1]) % mod

        ans = 0
        for i in range(1, m+1):
            ans = (ans + dp[i][k]) % mod

        return ans

