class Solution:
    def hasMatch(self, s: str, p: str) -> bool:
        return self.is_match(s, p)

    def is_match(self, s: str, p: str) -> bool:
        if len(p) == 0:
            return len(s) == 0

        if len(p) == 1:
            return len(s) == 1 and p[0] == s[0]

        if p[1] != '*':
            return len(s) > 0 and p[0] == s[0] and self.is_match(s[1:], p[1:])

        return self.is_match(s, p[2:]) or (len(s) > 0 and p[0] == s[0] and self.is_match(s[1:], p))

