        score = 0
        marked = set()
        for i in range(len(s)):
            if i not in marked:
                j = len(s) - 1
                while j > i and s[j] != chr(ord('a') + ord('z') - ord(s[i])):
                    j -= 1
                if j >= 0 and j not in marked:
                    marked.add(i)
                    marked.add(j)
                    score += i - j
        return score

