class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        res = []
        i, j = 0, 0
        direction = 'right'
        rows, cols = len(grid), len(grid[0])

        while i < rows and j < cols:
            res.append(grid[i][j])

            if direction == 'right':
                if j + 1 < cols:
                    j += 1
                else:
                    i += 1
                    direction = 'down'
            elif direction == 'down':
                if i + 1 < rows:
                    i += 1
                else:
                    j -= 1
                    direction = 'left'
            elif direction == 'left':
                if j - 1 >= 0:
                    j -= 1
                else:
                    i -= 1
                    direction = 'up'
            elif direction == 'up':
                if i - 1 >= 0:
                    i -= 1
                else:
                    j += 1
                    direction = 'right'

        return res

