class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        graph = defaultdict(list)
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        def dfs(node, parent):
            visited[node] = True
            max_weight = 0
            for neighbor, weight in graph[node]:
                if neighbor != parent:
                    if not visited[neighbor]:
                        max_weight = max(max_weight, dfs(neighbor, node))
                    else:
                        max_weight = max(max_weight, weight)
            return max_weight

        visited = [False] * n
        result = float('inf')
        for i in range(n):
            if not visited[i]:
                max_weight = dfs(i, None)
                if max_weight > threshold:
                    return -1
                result = min(result, max_weight)

        return result

