class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        mentions = [0] * numberOfUsers

        # Dictionary to store the current state of users
        user_state = collections.defaultdict(lambda: 'ONLINE')

        # Dictionary to keep track of the last seen timestamp for each user
        last_seen = collections.defaultdict(int)

        for event_type, timestamp, mentions_str in events:
            if event_type == 'MESSAGE':
                # Update the state of users based on the mentions string
                for user_id in mentions_str.split():
                    if user_id == 'ALL':
                        user_state[user_id] = 'ONLINE'
                    elif user_id == 'HERE':
                        user_state[user_id] = 'ONLINE'
                    else:
                        user_state[user_id] = 'OFFLINE'

                # Update the last seen timestamp for each user
                last_seen[user_id] = timestamp

                # Increment the mentions for each user
                for user_id in mentions_str.split():
                    mentions[int(user_id)] += 1
            elif event_type == 'OFFLINE':
                # Update the state of the user
                user_state[events[-1][2]] = 'OFFLINE'

                # Update the last seen timestamp for the user
                last_seen[events[-1][2]] = timestamp

        return mentions

