class Solution:
    def supersequences(self, words: List[str]) -> List[List[int]]:
        n = len(words)
        if n < 2:
            return [[]]

        # Create a graph where nodes are characters and edges are transitions between characters
        graph = defaultdict(list)
        for i in range(n):
            for j in range(i+1, n):
                if self.isSuperSequence(words[i], words[j]):
                    graph[words[i][0]].append(words[j][0])
                    graph[words[j][0]].append(words[i][0])

        # Perform topological sorting to find the longest path
        indegree = [0] * 26
        for node in graph:
            for neighbor in graph[node]:
                indegree[ord(neighbor)-ord('a')] += 1

        queue = deque([node for node in graph if indegree[node-ord('a')] == 0])
        result = []
        while queue:
            current_node = queue.popleft()
            result.append(current_node)
            for neighbor in graph[current_node]:
                indegree[ord(neighbor)-ord('a')] -= 1
                if indegree[ord(neighbor)-ord('a')] == 0:
                    queue.append(neighbor)

        # Convert the result list into the required format
        freqs = []
        for word in words:
            freq = [0] * 26
            for char in word:
                freq[ord(char)-ord('a')] += 1
            freqs.append(freq)

        return freqs

    def isSuperSequence(self, s1: str, s2: str) -> bool:
        i, j = 0, 0
        while i < len(s1) and j < len(s2):
            if s1[i] == s2[j]:
                i += 1
                j += 1
            else:
                i += 1
        return j == len(s2)

