from heapq import heappush, heappop

class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        rows, cols = len(grid), len(grid[0])
        heap = []

        # Push elements from the first row into the heap
        for j in range(cols):
            heappush(heap, (grid[0][j], 0, j))

        # Process each row starting from the second row
        for i in range(1, rows):
            while heap and heap[0][0] < grid[i][0]:
                _, r, c = heappop(heap)
                heappush(heap, (grid[i][c], i, c))

            heappush(heap, (grid[i][0], i, 0))

        # Place elements back into the original grid
        for i in range(rows):
            for j in range(cols):
                grid[i][j] = heappop(heap)[0]

        return grid

