class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        left, right = 0, sum(points)
        while left < right:
            mid = (left + right) // 2
            if self.canReachMid(points, m, mid):
                left = mid + 1
            else:
                right = mid
        return left - 1

    def canReachMid(self, points, m, mid):
        total_points = 0
        for point in points:
            if point > mid:
