class Solution:
    def separateSquares(self, squares: List[List[int]]) -> float:
        points = []
        for x, y, l in squares:
            points.append((x - l / 2, y))
            points.append((x + l / 2, y))
        points.sort()
        left = 0
        right = len(points)
        while left < right:
            mid = (left + right) // 2
            if self.is_valid(mid, points):
                right = mid
            else:
                left = mid + 1
        return (points[left][1] + points[right][1]) / 2

    def is_valid(self, mid, points):
        count = 0
        for i in range(len(points)):
            if points[i][0] > mid:
                break
            j = bisect.bisect_right(points, (mid + points[i][0], points[i][1]))
            count += j - i
        return count == len(squares)

