class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        nums = list(range(1, n + 1))
        for perm in permutations(nums):
            if self.is_alternating(perm):
                index = self.find_index(perm, k)
                return perm[:index] + perm[index+1:]
        return []

    def is_alternating(self, perm):
        return all(perm[i] % 2 != perm[i+1] % 2 for i in range(len(perm)-1))

    def find_index(self, perm, k):
        count = 0
        for i in range(len(perm)):
            if perm[i] % 2 == 0:
                count += 1
            if count >= k:
                return i
        return len(perm)

