class Solution:
    def longestSpecialPath(self, edges: List[List[int]], nums: List[int]) -> List[int]:
        graph = defaultdict(list)
        for u, v, _ in edges:
            graph[u].append(v)
            graph[v].append(u)

        def dfs(node):
            nonlocal max_path, min_path
            if len(graph[node]) == 1:
                return 1, 1

            left_max, left_min = 0, 1
            right_max, right_min = 0, 1

            for neighbor in graph[node]:
                if neighbor != parent:
                    lmax, lmin = dfs(neighbor)
                    if nums[node] == nums[neighbor]:
                        right_max = max(right_max, lmin + 1)
                    else:
