            max_path = max(max_path, left_max + right_max)
            min_path = min(min_path, left_max, right_max)

            return max(left_max, right_max), 1 + min(left_max, right_max)

        parent = None
        max_path, min_path = dfs(0)
        return [max_path, min_path]

