class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        res = 0
        for l, r in queries:
            res += self.minOpsHelper(l, r)
        return res

    def minOpsHelper(self, l, r):
        if l == r:
            return 0
        mid = (l + r) // 2
        left = self.minOpsHelper(l, mid)
        right = self.minOpsHelper(mid + 1, r)
        return left + right + self.countOps(l, mid) + self.countOps(mid + 1, r)

    def countOps(self, l, r):
        count = 0
        while l <= r:
            count += l % 4
            l //= 4
        return count

