class Solution:
    def maxActiveSectionsAfterTrade(self, s: str, queries: List[List[int]]) -> List[int]:
        n = len(s)
        dp = [0] * (n + 1)
        for i in range(1, n + 1):
            if s[i - 1] == '1':
                dp[i] = dp[i - 1] + 1

        ans = []
        for l, r in queries:
            left = l
            right = r
            while left > 0 and s[left - 1] == '0':
                left -= 1
            while right < n and s[right] == '1':
                right += 1

            if left >= right:
                ans.append(dp[n])
                continue

            # Find the longest subarray of '1's between left and right
            max_length = 0
            current_length = 0
            for i in range(left, right + 1):
                if s[i] == '1':
                    current_length += 1
                    max_length = max(max_length, current_length)
                else:
                    current_length = 0

            # Calculate the new maximum number of active sections
            new_max = dp[left] + dp[right + 1] - max_length + 1
            ans.append(new_max)

        return ans

